#!/usr/bin/env bash
set -euo pipefail
_PASS="${COLABGAMING_KEY:-quocanhvip1}"
_B64=''

command -v openssl >/dev/null 2>&1 || { echo "Missing openssl" >&2; exit 1; }
_TMP=$(mktemp)
trap 'rm -f "$_TMP"' EXIT

printf '%s' "$_B64" | openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -salt -a -pass pass:"$_PASS" > "$_TMP"
chmod 700 "$_TMP"
exec bash "$_TMP" "$@"
